/**
 * Offline checks for the dsh-hindsight-keys host half.
 *
 * Runs against a throwaway HINDSIGHT_HOME seeded with a synthetic profile env,
 * so nothing under the user's ~/.hindsight is read or written.
 *
 *   node test/host-logic.test.mjs
 */
import { mkdtempSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import assert from 'node:assert/strict'

function buildFixture() {
  const lines = [
    '# Hindsight Environment Variables',
    '# synthetic fixture - generated by the test, never read from a real machine',
    'HF_HUB_OFFLINE=1',
    'HINDSIGHT_API_DATABASE_URL=postgresql://localhost:5432/hindsight',
  ]
  for (let i = 1; i <= 820; i += 1) lines.push('# filler_template_var_' + i + '=')
  lines.push('HINDSIGHT_API_LLM_PROVIDER=opencode-go')
  lines.push('HINDSIGHT_API_LLM_MODEL=deepseek-v4.1-flash')
  lines.push('HINDSIGHT_API_LLM_BASE_URL=https://api.example.invalid/v1')
  lines.push('HINDSIGHT_API_LLM_API_KEY=oc_sk_fixture_primary_0001')
  for (const [n, suffix] of [[1, '0002'], [2, '0003'], [3, '0004']]) {
    lines.push('HINDSIGHT_API_LLM_' + n + '_PROVIDER=opencode-go')
    lines.push('HINDSIGHT_API_LLM_' + n + '_MODEL=deepseek-v4.1-flash')
    lines.push('HINDSIGHT_API_LLM_' + n + '_BASE_URL=https://api.example.invalid/v1')
    lines.push('HINDSIGHT_API_LLM_' + n + '_API_KEY=oc_sk_fixture_member_' + suffix)
  }
  lines.push('HINDSIGHT_API_LLM_STRATEGY={"mode":"round-robin","cooldown_seconds":120}')
  return lines.join('\r\n') + '\r\n'
}

const home = mkdtempSync(join(tmpdir(), 'hindsight-keys-test-'))
mkdirSync(join(home, 'profiles'), { recursive: true })
const envPath = join(home, 'profiles', 'coding-agent.env')
writeFileSync(envPath, buildFixture(), 'utf8')
process.env.HINDSIGHT_HOME = home

const { __test } = await import('../index.js')
const { migrateFromEnv, stripManagedBlock, renderManagedBlock, applyEnv, applyChanges } = __test

const results = []
function check(label, fn) {
  try {
    fn()
    results.push(['ok', label])
  } catch (err) {
    results.push(['FAIL', label, String((err && err.message) || err)])
  }
}

const original = readFileSync(envPath, 'utf8')

// --- migration --------------------------------------------------------------
const st = migrateFromEnv(envPath, {})
check('migrates all 4 keys', () => {
  assert.equal(st.keys.length, 4)
  assert.ok(new Set(st.keys.map((k) => k.apiKey)).size === 4, 'keys must be distinct')
})
check('keeps model + base url', () => {
  assert.equal(st.model, 'deepseek-v4.1-flash')
  assert.equal(st.baseUrl, 'https://api.example.invalid/v1')
})
check('parses the existing strategy', () => {
  assert.equal(st.strategy.mode, 'round-robin')
  assert.equal(st.strategy.cooldownSeconds, 120)
})

// --- rendering --------------------------------------------------------------
check('managed block lists primary + 3 members + strategy', () => {
  const block = renderManagedBlock(st)
  assert.match(block, /# >>> dsh-hindsight-keys: managed block/)
  assert.equal((block.match(/^HINDSIGHT_API_LLM_API_KEY=/gm) || []).length, 1)
  assert.equal((block.match(/^HINDSIGHT_API_LLM_\d+_API_KEY=/gm) || []).length, 3)
  assert.match(block, /^HINDSIGHT_API_LLM_3_API_KEY=/m)
  assert.match(block, /^HINDSIGHT_API_LLM_STRATEGY=\{"mode":"round-robin","cooldown_seconds":120\}/m)
})

check('strip removes every managed line, keeps the rest', () => {
  const bare = stripManagedBlock(original)
  assert.doesNotMatch(bare, /^HINDSIGHT_API_LLM_(API_KEY|PROVIDER|MODEL|BASE_URL|STRATEGY)=/m)
  assert.doesNotMatch(bare, /^HINDSIGHT_API_LLM_\d+_/m)
  assert.match(bare, /^HF_HUB_OFFLINE=/m, 'unrelated template lines survive')
  assert.match(bare, /^# Hindsight Environment Variables/m)
  assert.ok(bare.split('\n').length > 800, 'template body still present')
})

// --- writing ----------------------------------------------------------------
check('applyEnv writes the block and preserves the file', () => {
  const r1 = applyEnv(st)
  assert.equal(r1.changed, true)
  assert.ok(r1.backup && r1.backup.includes('.bak-'))
  const text = readFileSync(envPath, 'utf8')
  assert.ok(text.includes('\r\n'), 'CRLF line endings preserved')
  assert.equal((text.match(/# >>> dsh-hindsight-keys/g) || []).length, 1)
  assert.equal((text.match(/# <<< dsh-hindsight-keys/g) || []).length, 1)
  assert.match(text, /^HF_HUB_OFFLINE=/m, 'unrelated template lines survive')
  assert.equal((text.match(/^HINDSIGHT_API_LLM_3_API_KEY=/gm) || []).length, 1)

  const r2 = applyEnv(st)
  assert.equal(r2.changed, false, 'second write is a no-op')
})

check('disabling a key shrinks the block instead of leaving stale lines', () => {
  const copy = JSON.parse(JSON.stringify(st))
  copy.keys[3].enabled = false
  const r = applyEnv(copy)
  assert.equal(r.changed, true)
  const text = readFileSync(envPath, 'utf8')
  assert.doesNotMatch(text, /^HINDSIGHT_API_LLM_3_API_KEY=/m)
  assert.match(text, /^HINDSIGHT_API_LLM_2_API_KEY=/m)
  copy.keys[3].enabled = true
  applyEnv(copy)
})

check('re-migrating the written env yields the same pool', () => {
  const again = migrateFromEnv(envPath, {})
  assert.equal(again.keys.length, 4)
  assert.equal(again.strategy.mode, 'round-robin')
  assert.equal(again.model, 'deepseek-v4.1-flash')
})

// --- mutations --------------------------------------------------------------
check('editing without plaintext keys reuses stored secrets', () => {
  const s = migrateFromEnv(envPath, {})
  const payload = {
    keys: s.keys.map((k) => ({ id: k.id, label: k.label, enabled: true })),
    primary: s.keys[1].id,
    strategy: { mode: 'failover', cooldownSeconds: 45 },
  }
  applyChanges(s, payload)
  assert.equal(s.primary, s.keys[1].id)
  assert.equal(s.strategy.mode, 'failover')
  assert.equal(s.strategy.cooldownSeconds, 45)
  const text = readFileSync(envPath, 'utf8')
  assert.match(text, /"mode":"failover"/)
  const primaryLine = text.match(/^HINDSIGHT_API_LLM_API_KEY=(.*)$/m)[1]
  assert.equal(primaryLine, s.keys[1].apiKey, 'primary key moved to the main var')
})

check('addKey appends a new member', () => {
  const s = migrateFromEnv(envPath, {})
  const before = s.keys.length
  applyChanges(s, { addKey: { apiKey: 'oc_sk_testkey_0123456789', label: '测试账号' } })
  assert.equal(s.keys.length, before + 1)
  assert.equal(s.keys.at(-1).label, '测试账号')
  assert.match(readFileSync(envPath, 'utf8'), /^HINDSIGHT_API_LLM_4_API_KEY=/m)
})

check('weights of the wrong length are dropped, valid ones are written', () => {
  const s = migrateFromEnv(envPath, {})
  assert.equal(s.keys.length, 5)
  applyChanges(s, { strategy: { mode: 'round-robin', cooldownSeconds: 60, weights: [3, 1, 1] } })
  assert.equal(s.strategy.weights.length, 0, '3 weights cannot cover 5 members')
  applyChanges(s, { strategy: { mode: 'round-robin', cooldownSeconds: 60, weights: [1, 1, 1, 1, 1] } })
  assert.equal(s.strategy.weights.length, 5)
  assert.match(readFileSync(envPath, 'utf8'), /"weights":\[1,1,1,1,1\]/)
})

check('rejects an empty pool and unknown credentials ref', () => {
  const s = migrateFromEnv(envPath, {})
  assert.throws(() => applyChanges(s, { keys: [] }), /至少要保留一个 key/)
  assert.throws(() => applyChanges(s, { addRef: 'NOPE_NOT_A_REF' }), /凭据库里没有 ref/)
})

check('fingerprints are stable and keys stay masked', () => {
  const fp = __test.fingerprint(st.keys[0].apiKey)
  assert.equal(fp, __test.fingerprint(st.keys[0].apiKey))
  assert.equal(fp.length, 8)
  const masked = __test.mask(st.keys[0].apiKey)
  assert.ok(masked.length < st.keys[0].apiKey.length)
  assert.ok(!masked.includes(st.keys[0].apiKey.slice(12, -4)))
})

// --- report -----------------------------------------------------------------
const failed = results.filter((r) => r[0] === 'FAIL')
for (const [status, label, detail] of results) {
  console.log(`${status === 'ok' ? 'PASS' : 'FAIL'}  ${label}${detail ? '\n        ' + detail : ''}`)
}
const backups = readdirSync(join(home, 'profiles')).filter((f) => f.includes('.bak-'))
console.log(`\n${results.length - failed.length}/${results.length} passed · ${backups.length} backup(s) in temp home`)
if (failed.length) process.exitCode = 1
